import random, sys
sys.path[:0]=['/workspace/tmp/tests']
from brute import compare

NAMES=['A','B','C']
def gen_path(rng, maxlen):
    n=rng.randint(0,maxlen)
    return ','.join(rng.choice(NAMES) for _ in range(n))
def gen_pred(rng, depth):
    if depth>=3 or rng.random()<0.45:
        op=rng.choice(['match','match','match','startswith','endswith','contains'])
        return '%s(%s)'%(op,gen_path(rng,3))
    kind=rng.random()
    if kind<0.2:
        return 'not(%s)'%gen_pred(rng,depth+1)
    op=rng.choice(['and','or'])
    return '(%s %s %s)'%(gen_pred(rng,depth+1),op,gen_pred(rng,depth+1))
def gen_policy(rng):
    parts=[]
    for _ in range(rng.randint(0,4)):
        parts.append('%s %s;'%(gen_pred(rng,0), rng.choice(['allow','allow','drop'])))
    return ' '.join(parts)

def main():
    seed=int(sys.argv[1]); count=int(sys.argv[2]); dw=int(sys.argv[3]); dc=int(sys.argv[4])
    rng=random.Random(seed)
    labels=rng.sample(range(1,4294967294),len(NAMES))
    reg=[{'name':n,'label':labels[i]} for i,n in enumerate(NAMES)]
    bad=0; skipped=0; done=0
    for i in range(count):
        p=gen_policy(rng)
        try:
            ok=compare(p,reg,dw=dw,dc=dc,verbose=(bad<2))
        except Exception as e:
            skipped+=1
            continue
        done+=1
        if not ok:
            bad+=1
            print('FAIL seed',seed,i,repr(p))
            if bad>3: break
    print('fuzz seed',seed,'checked',done,'failures',bad,'skipped',skipped)
main()
